insert into activities (slug,title,category,description,min_age,max_age,multi_age_note,setting,weather_fit,cost_band,price_note,duration_min,booking_required,opening_note,source_url,status,is_demo,last_checked,season_months) values ('museo-patrimonio-industriale','Museo del Patrimonio Industriale','museo','Museo nell''ex fornace Galotti su industria, macchine e lavoro nella storia di Bologna. Macchinari e percorsi visivi parlano ai piccoli, il contesto storico ai più grandi.',5,14,'Piccoli: osservano macchine e modelli. Grandi: seguono la storia del lavoro e dell''energia.','indoor','rain_ok','low','Intero 5 €, ridotto 2-3 €; gratis con Card Cultura o Bologna Welcome Card',90,null,'Gio-ven 9-13; sab-dom 10-18:30. Estate (15/7-18/9) solo ven mattina su prenotazione','https://www.bolognawelcome.com/en/luoghi/musei-e-gallerie-darte/museo-del-patrimonio-industriale-fornace-galotti','da_verificare',true,'2026-11-01',null) on conflict (slug) do nothing;
insert into activities (slug,title,category,description,min_age,max_age,multi_age_note,setting,weather_fit,cost_band,price_note,duration_min,booking_required,opening_note,source_url,status,is_demo,last_checked,season_months) values ('biblioteca-salaborsa-ragazzi','Biblioteca Salaborsa e Salaborsa Ragazzi','biblioteca','Biblioteca civica in Palazzo d''Accursio con spazi per bambini e ragazzi (anche sala 0-3 anni) e scavi archeologici sotto la piazza coperta. Ingresso libero, ottimo rifugio quando piove.',0,14,'Piccoli: sala 0-3 e albi illustrati. Grandi: scaffali ragazzi, studio e scavi romani da guardare.','indoor','rain_ok','free','Ingresso gratuito',90,false,'Lun 14-20; mar-ven 9-20; sab 9-19; dom chiuso','https://www.bolognawelcome.com/it/luoghi/biblioteche/salaborsa-','da_verificare',true,'2026-11-01',null) on conflict (slug) do nothing;
insert into activities (slug,title,category,description,min_age,max_age,multi_age_note,setting,weather_fit,cost_band,price_note,duration_min,booking_required,opening_note,source_url,status,is_demo,last_checked,season_months) values ('museo-palazzo-poggi','Museo di Palazzo Poggi','museo','Museo universitario di scienze in un palazzo storico: navi, carte geografiche, fisica e storia naturale. Le sale con le cere anatomiche sono più adatte ai ragazzi grandi.',6,17,'Piccoli: navi, strumenti e modelli. Grandi: collezioni scientifiche e cere anatomiche (più impressionanti).','indoor','rain_ok','low','Intero 7 €; secondo tariffario SMA gratis sotto i 18 anni (da verificare)',90,null,'Orari non verificati: vedi sma.unibo.it','https://www.cittametropolitana.bo.it/cultura/guidaMusei/Titolari_1/Percorsi/guidaMusei/Guida_Musei_Distretti_culturali/Museo_di_Palazzo_Poggi','da_verificare',true,'2026-11-01',null) on conflict (slug) do nothing;
insert into activities (slug,title,category,description,min_age,max_age,multi_age_note,setting,weather_fit,cost_band,price_note,duration_min,booking_required,opening_note,source_url,status,is_demo,last_checked,season_months) values ('museo-capellini-geologia','Museo Capellini (Geologia e Paleontologia)','scienza','Museo di geologia con un modello di diplodoco lungo circa 26 metri, uno scheletro di mastodonte e balene fossili. Dinosauri per i piccoli, fossili ed ere geologiche per i grandi.',4,14,'Piccoli: il diplodoco e gli scheletri giganti. Grandi: fossili, ere geologiche, schede da leggere.','indoor','rain_ok','low','Intero 5 €, ridotto 3 €; gratis sotto i 18 anni secondo tariffario SMA (da verificare)',60,null,'Mar-ven 9-13; sab, dom e festivi 10-18; chiuso lun non festivi','https://www.bolognawelcome.com/it/luoghi/musei-e-collezioni-private/collezione-di-geologia-giovanni-capellini','da_verificare',true,'2026-11-01',null) on conflict (slug) do nothing;
insert into activities (slug,title,category,description,min_age,max_age,multi_age_note,setting,weather_fit,cost_band,price_note,duration_min,booking_required,opening_note,source_url,status,is_demo,last_checked,season_months) values ('torre-della-specola','Museo della Specola (torre di Palazzo Poggi)','scienza','Visita guidata alle collezioni di astronomia e salita alla terrazza della torre (272 gradini). Per bambini che reggono scale e gruppo guidato; strumenti e globi affascinano diverse età.',6,17,'Piccoli: globi e strumenti curiosi (ma 272 gradini). Grandi: spiegazioni di astronomia e vista dall''alto.','indoor','rain_ok','low','Guidata con terrazza: intero 10 €, 5 € per 7-18 anni, gratis 0-6; solo terrazza 5 € (gratis sotto i 18)',90,true,'Visite guidate mar-dom a orari specifici, max 15 persone; riapertura dopo i lavori 2024 da confermare','https://sma.unibo.it/en/the-university-museum-network/specola-museum-of-astronomy/specola-museum-of-astronomy','draft',true,'2026-11-01',null) on conflict (slug) do nothing;
insert into activities (slug,title,category,description,min_age,max_age,multi_age_note,setting,weather_fit,cost_band,price_note,duration_min,booking_required,opening_note,source_url,status,is_demo,last_checked,season_months) values ('museo-ducati-fisica-in-moto','Museo Ducati e Fisica in Moto','scienza','Museo delle moto Ducati dentro lo stabilimento di Borgo Panigale; la Fondazione Ducati propone anche il laboratorio interattivo Fisica in Moto. Moto da corsa per tutti, la fisica per i più grandi.',5,17,'Piccoli: moto e colori da guardare da vicino. Grandi: tecnica, storia delle corse e laboratorio di fisica.','indoor','rain_ok','mid','Museo: intero 17-18 € (+2 € prevendita), ridotto 15-16 €; tariffe bambini e Fisica in Moto da verificare',90,true,'9-18; fonti discordanti su chiusura del mercoledì; ingresso con biglietto orario online','https://www.ducati.com/ch/it/borgo-panigale-experience/museo-ducati','da_verificare',true,'2026-11-01',null) on conflict (slug) do nothing;
insert into activities (slug,title,category,description,min_age,max_age,multi_age_note,setting,weather_fit,cost_band,price_note,duration_min,booking_required,opening_note,source_url,status,is_demo,last_checked,season_months) values ('museo-storia-bologna-palazzo-pepoli','Museo della Storia di Bologna (Palazzo Pepoli)','museo','Mille anni di storia cittadina raccontati in un palazzo nobiliare, con una sezione dedicata ai burattini. In alcune date ci sono tour pensati per famiglie con bambini dai 4 ai 12 anni.',5,14,'Piccoli: burattini e sale spettacolari. Grandi: la storia di Bologna con percorsi tematici.','indoor','rain_ok','low','Tour famiglie (date programmate): bimbo 4-12 anni 7 €, adulto 15 €. Biglietto museo da verificare',90,null,'Chiuso il martedì (da fonte secondaria); orari da verificare su palazzopepoli.it','https://www.bolognawelcome.com/it/luoghi/musei-e-gallerie-darte/palazzo-pepoli-museo-della-storia-di-bologna','da_verificare',true,'2026-11-01',null) on conflict (slug) do nothing;
insert into activities (slug,title,category,description,min_age,max_age,multi_age_note,setting,weather_fit,cost_band,price_note,duration_min,booking_required,opening_note,source_url,status,is_demo,last_checked,season_months) values ('museo-civico-archeologico','Museo Civico Archeologico','museo','Museo su Piazza Maggiore con sezione egizia e reperti etruschi e romani. Con i più piccoli si scelgono poche sale; i ragazzi possono approfondire con le guide.',6,17,'Piccoli: poche sale (egizia, mummie). Grandi: sale etrusche e romane, visite guidate.','indoor','rain_ok','low','Intero 6 €, ridotto 2-4 €; gratis con Card Cultura o Bologna Welcome Card',90,null,'Orario invernale dal 3/11/2025: lun, mer-ven 9-18; sab-dom e festivi 10-19; mar chiuso (pagina incoerente, verificare)','https://www.bolognawelcome.com/it/luoghi/musei-e-collezioni-private/museo-civico-archeologico','da_verificare',true,'2026-11-01',null) on conflict (slug) do nothing;
insert into activities (slug,title,category,description,min_age,max_age,multi_age_note,setting,weather_fit,cost_band,price_note,duration_min,booking_required,opening_note,source_url,status,is_demo,last_checked,season_months) values ('museo-internazionale-musica','Museo internazionale e biblioteca della musica','museo','Museo di strumenti antichi e storia della musica in Palazzo Aldini Sanguinetti, in Strada Maggiore. Piace ai curiosi di suoni; i ragazzi seguono la storia degli strumenti.',5,17,'Piccoli: strumenti strani e dipinti da osservare. Grandi: storia della musica e collezioni.','indoor','rain_ok','low','Intero 5 €, ridotto 3 €; gratis con Card Cultura o Bologna Welcome Card',75,null,'Mar-gio 11-13:30 e 14:30-18:30; ven 10-13:30 e 14:30-19; sab-dom 10-19; lun chiuso','https://www.bolognawelcome.com/it/luoghi/musei-e-gallerie-darte/museo-internazionale-e-biblioteca-della-musica','da_verificare',true,'2026-11-01',null) on conflict (slug) do nothing;
insert into activities (slug,title,category,description,min_age,max_age,multi_age_note,setting,weather_fit,cost_band,price_note,duration_min,booking_required,opening_note,source_url,status,is_demo,last_checked,season_months) values ('mambo-museo-arte-moderna','MAMbo - Museo d''Arte Moderna','museo','Museo d''arte moderna e contemporanea con attività educative per famiglie (da richiedere). Il biglietto vale anche per il Museo Morandi. Visita breve e mirata funziona con età miste.',6,17,'Piccoli: opere grandi e colorate, visita breve. Grandi: contenuti e idee dietro le opere.','indoor','rain_ok','low','Intero 6 €, ridotto 4 €; include Museo Morandi; gratis con Card Cultura o Bologna Welcome Card',75,null,'Mar 14-18:30; mer e ven 9:30-18:30; gio 9:30-20; sab-dom 10-19; lun chiuso','https://www.bolognawelcome.com/it/luoghi/musei-e-collezioni-private/mambo---museo-darte-moderna-di-bologna','da_verificare',true,'2026-11-01',null) on conflict (slug) do nothing;
insert into activities (slug,title,category,description,min_age,max_age,multi_age_note,setting,weather_fit,cost_band,price_note,duration_min,booking_required,opening_note,source_url,status,is_demo,last_checked,season_months) values ('giocars-museo-giocattolo-movimento','Giocars - Museo del giocattolo in movimento','laboratorio','Museo di giocattoli in movimento a Sala Bolognese, con visite guidate per famiglie e laboratori per bambini e ragazzi. Piccoli e grandi sono accomunati dal fascino dei giochi che si muovono.',3,14,'Piccoli: giocattoli in movimento da guardare. Grandi: storia dei giocattoli e laboratori.','indoor','rain_ok','low','Intero 8 €, ridotto 3-5 €; visita guidata 10 €',75,null,'Orari su giocars.it/info (non verificati)','https://www.bolognawelcome.com/it/luoghi/musei-e-collezioni-private/giocars---museo-del-giocattolo-in-movimento','da_verificare',true,'2026-11-01',null) on conflict (slug) do nothing;
