insert into activities (slug,title,category,description,min_age,max_age,multi_age_note,setting,weather_fit,cost_band,price_note,duration_min,booking_required,opening_note,source_url,status,is_demo,last_checked,season_months) values ('oasi-la-rizza','Oasi La Rizza','natura','Ex risaia trasformata in oasi per uccelli, con capanni e torri per osservarli e il ritorno delle cicogne. Sentieri piani: i piccoli passeggiano, i grandi fanno i birdwatcher.',3,17,'Piccoli: passeggiata tra gli uccelli. Grandi: osservazione e fotografia naturalistica.','outdoor','dry_only','free','Accesso libero',90,false,'Accesso libero dall''alba al tramonto','https://www.bolognawelcome.com/it/luoghi/parchi-e-giardini/oasi-la-rizza','da_verificare',true,'2026-11-01',null) on conflict (slug) do nothing;
