insert into activities (slug,title,category,description,min_age,max_age,multi_age_note,setting,weather_fit,cost_band,price_note,duration_min,booking_required,opening_note,source_url,status,is_demo,last_checked,season_months) values ('chiusa-di-casalecchio','Chiusa di Casalecchio e Parco della Chiusa','natura','Diga storica sul Reno con passeggiata sul fiume e parco della Chiusa, ex tenuta Sampieri Talon. Spazio per pic-nic e per capire come il canale muoveva i mulini di Bologna.',3,17,'Piccoli: acqua e prati. Grandi: storia del canale e delle sue funzioni.','outdoor','dry_only','free','Passeggiata sul fiume; costi e visite guidate del Consorzio da verificare',90,false,null,'https://www.italia.it/it/emilia-romagna/bologna/chiusa-di-casalecchio','da_verificare',true,'2026-11-01',null) on conflict (slug) do nothing;
insert into activities (slug,title,category,description,min_age,max_age,multi_age_note,setting,weather_fit,cost_band,price_note,duration_min,booking_required,opening_note,source_url,status,is_demo,last_checked,season_months) values ('portico-san-luca','Portico e Santuario di San Luca','gita','Salita di circa 3,6-3,8 km sotto il portico più lungo del mondo fino al santuario, con sosta all''Arco del Meloncello. Si può dividere in tappe o scegliere il trenino turistico.',4,17,'Piccoli: contano gli archi e fanno pause. Grandi: arrivano in cima e scendono a piedi.','outdoor','any','free','Portico gratuito; trenino San Luca Express a pagamento',180,false,'Orari del santuario non verificati (santuariodisanluca.it)','https://www.italia.it/it/emilia-romagna/bologna/santuario-madonna-di-san-luca','da_verificare',true,'2026-11-01',null) on conflict (slug) do nothing;
insert into activities (slug,title,category,description,min_age,max_age,multi_age_note,setting,weather_fit,cost_band,price_note,duration_min,booking_required,opening_note,source_url,status,is_demo,last_checked,season_months) values ('ciclovia-del-navile','Ciclovia del Canale Navile','sport','Percorso in bici lungo il canale Navile da Bologna verso Bentivoglio: piste, sterrati e strade secondarie, con tappe come Villa Smeraldi e Oasi La Rizza. Si accorcia a piacere.',5,17,'Piccoli: tratti brevi e pause. Grandi: tappe più lunghe fino a Bentivoglio.','outdoor','dry_only','free','Accesso libero',180,false,'Percorso lungo il canale: nessun orario','https://emiliaromagnaturismo.it/en/itineraries/navile-cycle-route','da_verificare',true,'2026-11-01',null) on conflict (slug) do nothing;
insert into activities (slug,title,category,description,min_age,max_age,multi_age_note,setting,weather_fit,cost_band,price_note,duration_min,booking_required,opening_note,source_url,status,is_demo,last_checked,season_months) values ('parco-avventura-cavaioni','Cavaioni Park (parco avventura)','sport','Parco avventura sugli alberi con percorsi baby e junior (da 100 cm) e percorsi avventura (da 140 cm): ogni fratello trova il proprio livello. Apertura stagionale.',4,17,'Piccoli: percorsi baby da 100 cm. Grandi: percorsi avventura da 140 cm.','outdoor','dry_only','mid','Dati 2024: ridotto (da 100 cm) 20 €, intero (da 140 cm) 25 €',180,null,'Stagionale: nel 2024 aprile-ottobre (weekend in primavera e autunno, tutti i giorni in estate tranne lun); gruppi su prenotazione','https://www.bolognawelcome.com/it/luoghi/parchi-tematici/parco-avventura-cavaioni','draft',true,'2026-11-01',null) on conflict (slug) do nothing;
insert into activities (slug,title,category,description,min_age,max_age,multi_age_note,setting,weather_fit,cost_band,price_note,duration_min,booking_required,opening_note,source_url,status,is_demo,last_checked,season_months) values ('fattoria-didattica-monte-san-pietro','Visita in fattoria didattica con merenda (Monte San Pietro)','fattoria','Visita di un''ora in una piccola fattoria: asino, capra, coniglio e agnello da accarezzare e dare da mangiare, poi merenda casalinga. Per famiglie, gruppi fino a 15 persone.',2,14,'Piccoli: accarezzano gli animali. Grandi: imparano come si curano e cosa mangiano.','outdoor','dry_only','mid','Da 15 € a persona',60,true,'Esperienza proposta da gennaio a settembre (non attiva ott-dic); indirizzo comunicato dopo la prenotazione','https://freedome.it/attivita/visita-fattoria-didattica-merenda-monte-san-pietro-bologna/','draft',true,'2026-11-01',null) on conflict (slug) do nothing;
insert into activities (slug,title,category,description,min_age,max_age,multi_age_note,setting,weather_fit,cost_band,price_note,duration_min,booking_required,opening_note,source_url,status,is_demo,last_checked,season_months) values ('parco-gessi-bolognesi-farneto','Parco dei Gessi Bolognesi e Calanchi dell''Abbadessa (Farneto)','natura','Parco regionale con affioramenti di gesso, doline e oltre 130 grotte, sito UNESCO, a meno di 20 km dal centro. Sentieri per camminare in famiglia; visite alle grotte da verificare.',6,17,'Piccoli: sentieri semplici e doline. Grandi: geologia e grotte (se concordate).','outdoor','dry_only','free','Accesso al parco libero; visite in grotta da verificare',150,null,null,'https://bolognawelcome.com/en/places/parks-and-gardens/parco-dei-gessi--2','da_verificare',true,'2026-11-01',null) on conflict (slug) do nothing;
insert into activities (slug,title,category,description,min_age,max_age,multi_age_note,setting,weather_fit,cost_band,price_note,duration_min,booking_required,opening_note,source_url,status,is_demo,last_checked,season_months) values ('san-michele-in-bosco-forte-bandiera','San Michele in Bosco e Forte Bandiera','natura','Salita breve nel parco del complesso di San Michele in Bosco (colle di circa 132 m), con panorama sulla città. Passeggiata di 1-2 ore, salita costante; passeggino difficile.',5,14,'Piccoli: tratto breve, si ferma a metà e gioca con foglie e ghiande. Grandi: arrivano in cima e collegano Forte Bandiera e Villa Ghigi.','outdoor','dry_only','free','Ingresso libero',90,false,'Parco aperto 24 ore (fonte Bologna Welcome). coordinate approssimate','https://www.bolognawelcome.com/home/scopri/luoghi/natura-e-paesaggio/parchi-e-giardini/parco-di-san-michele-in-bosco','da_verificare',true,'2026-11-02',null) on conflict (slug) do nothing;
insert into activities (slug,title,category,description,min_age,max_age,multi_age_note,setting,weather_fit,cost_band,price_note,duration_min,booking_required,opening_note,source_url,status,is_demo,last_checked,season_months) values ('contrafforte-pliocenico-monte-adone','Contrafforte Pliocenico: guglie di Sasso Marconi','natura','Riserva con pareti di arenaria piena di fossili marini, a circa 20 km da Bologna. Si fa un tratto facile su sentiero 1,5-3 ore; i sentieri alti sono ripidi, passeggino no.',7,14,'Piccoli: cercano conchiglie fossili nelle rocce con un adulto vicino. Grandi: salgono ai punti panoramici sulle guglie.','outdoor','dry_only','free',null,150,false,'Ravine e microhabitat difficili da raggiungere, restare sui sentieri. coordinate approssimate (centro Sasso Marconi); partenza e lunghezze da verificare.','https://appenninobolognese.cittametropolitana.bo.it/en/places/parks-and-gardens/contrafforte-pliocenico-nature-reserve','da_verificare',true,'2026-11-02','{3,4,5,6,9,10,11}') on conflict (slug) do nothing;
insert into activities (slug,title,category,description,min_age,max_age,multi_age_note,setting,weather_fit,cost_band,price_note,duration_min,booking_required,opening_note,source_url,status,is_demo,last_checked,season_months) values ('monte-sole-san-martino','Parco storico di Monte Sole: Poggiolo e San Martino','natura','Tratto facile attorno al centro visite Poggiolo e a San Martino, nel parco della memoria. Passeggiata breve di 1-2 ore, quasi in piano; gli anelli lunghi sono per i più grandi.',6,14,'Piccoli: sentiero breve e prati, senza salite. Grandi: Memoriale fino alla cima e storia del luogo con un adulto.','outdoor','dry_only','free',null,120,null,'Percorso Memoriale parte dal Poggiolo. Evento maggio 2026 ''breve passeggiata a San Martino'' per accessibilità. Luogo di memoria: rispetto e silenzio.','https://appenninobolognese.cittametropolitana.bo.it/en/places/parks-and-gardens/monte-sole-historical-park','da_verificare',true,'2026-11-02','{3,4,5,6,9,10,11}') on conflict (slug) do nothing;
insert into activities (slug,title,category,description,min_age,max_age,multi_age_note,setting,weather_fit,cost_band,price_note,duration_min,booking_required,opening_note,source_url,status,is_demo,last_checked,season_months) values ('lago-suviana-giro-del-lago','Lago di Suviana: giro del lago','natura','Giro facile, prevalentemente pianeggiante, attorno al lago di Suviana con aree picnic e punti panoramici. A settembre-ottobre si sentono i bramiti dei cervi. Passeggino parziale.',3,14,'Piccoli: sosta picnic e acqua. Grandi: sentieri laterali verso Monte Stagno e il castagneto del Poranceto.','outdoor','dry_only','free',null,150,false,'Lunghezza e durata del giro non indicate dalla fonte. coordinate approssimate. Tel. Centro Velico Suviana 053 4446712.','https://travel.thewom.it/italia/emilia-romagna/bologna/laghi-di-suviana-e-brasimone.html','da_verificare',true,'2026-11-02','{4,5,6,7,8,9,10}') on conflict (slug) do nothing;
insert into activities (slug,title,category,description,min_age,max_age,multi_age_note,setting,weather_fit,cost_band,price_note,duration_min,booking_required,opening_note,source_url,status,is_demo,last_checked,season_months) values ('lago-brasimone-chiapporato','Lago del Brasimone e borgo di Chiapporato','natura','Cammino nel bosco dal lago del Brasimone fino ai ruderi di Chiapporato tra castagneti secolari. Escursione di mezza giornata, saliscendi leggeri; passeggino no.',6,14,'Piccoli: tratto verso il lago e i castagni, poi tornano. Grandi: raggiungono le rovine del borgo abbandonato.','outdoor','dry_only','free',null,180,false,'Lunghezza non indicata dalla fonte. coordinate approssimate. Fine settembre-ottobre: bramiti dei cervi.','https://travel.thewom.it/italia/emilia-romagna/bologna/laghi-di-suviana-e-brasimone.html','da_verificare',true,'2026-11-02','{5,6,7,8,9,10}') on conflict (slug) do nothing;
insert into activities (slug,title,category,description,min_age,max_age,multi_age_note,setting,weather_fit,cost_band,price_note,duration_min,booking_required,opening_note,source_url,status,is_demo,last_checked,season_months) values ('cascate-dardagna-santuario-acero','Cascate del Dardagna dal Santuario dell''Acero','natura','Sentiero CAI 331 dal Santuario Madonna dell''Acero: circa 3 km andata e ritorno, 1h30, dislivello minimo. Cascate in sette salti nel bosco di faggi. Passeggino no.',4,14,'Piccoli: sentiero facile, sosta alle prime cascate. Grandi: possono provare l''anello più lungo CAI 333 con gradini.','outdoor','dry_only','free',null,90,false,'Rocce vicino all''acqua scivolose dopo la pioggia. Coordinate del parco Corno alle Scale. Santuario con orari più regolari maggio-settembre.','https://www.idealista.it/news/node/343269','da_verificare',true,'2026-11-02','{5,6,7,8,9,10}') on conflict (slug) do nothing;
insert into activities (slug,title,category,description,min_age,max_age,multi_age_note,setting,weather_fit,cost_band,price_note,duration_min,booking_required,opening_note,source_url,status,is_demo,last_checked,season_months) values ('corno-alle-scale-laghetto-cavone','Corno alle Scale: laghetto del Cavone','natura','Escursione facile nel parco regionale Corno alle Scale, dal Santuario dell''Acero al laghetto del Cavone, fra faggete e pascoli. Durata circa 2 ore, ambiente di montagna.',6,14,'Piccoli: laghetto e prati in alto. Grandi: fanno il giro dei sentieri CAI e osservano la flora di quota.','outdoor','dry_only','free',null,150,false,'Escursione citata nel programma Ente Parchi (maggio 2026), lunghezza non indicata. Coordinate del parco. Neve in inverno.','https://www.dire.it/19-05-2026/1241178-parchi-nel-bolognese-venite-a-scoprire-i-gioielli-naturali-in-appennino/','da_verificare',true,'2026-11-02','{6,7,8,9,10}') on conflict (slug) do nothing;
